<script setup>
import { computed,ref,watch } from 'vue'
import { Search, Plus, Trash2, Pencil, X, Info } from 'lucide-vue-next'
const props=defineProps({section:String,title:String})
const seed={pasien:[['PS-001','Contoh Pasien A','Umum','Aktif'],['PS-002','Contoh Pasien B','KIA','Aktif']],pelayanan:[['LY-001','Pelayanan Umum','Senin–Sabtu','Aktif'],['LY-002','Kesehatan Ibu dan Anak','Senin–Jumat','Aktif']],pegawai:[['PG-001','Contoh Pegawai A','Perawat','Aktif'],['PG-002','Contoh Pegawai B','Administrasi','Aktif']],artikel:[['AR-001','Pentingnya Cuci Tangan','Edukasi','Draft'],['AR-002','Pola Hidup Bersih dan Sehat','Kesehatan','Draft']],kegiatan:[['KG-001','Edukasi Cuci Tangan','Penyuluhan','Rencana']],jadwal:[['JD-001','Pelayanan Umum','Senin–Sabtu','Aktif']],laporan:[['LP-001','Rekap Kunjungan','Bulanan','Draft']],pengaturan:[['ST-001','Profil Puskesmas','Umum','Aktif']]}
const storageKey=computed(()=>`kesambi-demo-${props.section}`)
function load(){try{return JSON.parse(localStorage.getItem(storageKey.value))??seed[props.section]??[]}catch{return seed[props.section]??[]}}
const rows=ref(load()),search=ref(''),editing=ref(-1),modal=ref(false),form=ref(['','','','Aktif'])
watch(()=>props.section,()=>{rows.value=load();search.value='';modal.value=false})
const filtered=computed(()=>rows.value.map((row,index)=>({row,index})).filter(x=>x.row.join(' ').toLowerCase().includes(search.value.toLowerCase())))
function persist(){localStorage.setItem(storageKey.value,JSON.stringify(rows.value))}
function startAdd(){editing.value=-1;form.value=['','','','Aktif'];modal.value=true}
function startEdit(i){editing.value=i;form.value=[...rows.value[i]];modal.value=true}
function save(){if(!form.value[0].trim()||!form.value[1].trim())return;if(editing.value===-1)rows.value.push([...form.value]);else rows.value[editing.value]=[...form.value];persist();modal.value=false}
function remove(i){if(confirm('Hapus data demo ini?')){rows.value.splice(i,1);persist()}}
function csv(){const lines=[['Kode','Nama / Keterangan','Kategori / Jadwal','Status'],...rows.value].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${props.section}-demo.csv`;a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="demo-banner"><Info :size="17"/> Data di halaman ini hanya contoh dan tersimpan lokal pada browser ini, bukan di server Puskesmas.</div><div class="page-heading"><div><h1>{{title}}</h1><p>Kelola informasi {{title.toLowerCase()}} dengan mudah.</p></div><div class="heading-actions"><button class="secondary-button" @click="csv">Ekspor CSV</button><button class="primary-button" @click="startAdd"><Plus :size="18"/> Tambah Data</button></div></div><section class="panel table-panel"><div class="table-toolbar"><div class="search-box"><Search :size="18"/><input v-model="search" placeholder="Cari data..." /></div><span class="record-count">{{filtered.length}} data ditemukan</span></div><div class="table-scroll"><table><thead><tr><th>Kode</th><th>Nama / Keterangan</th><th>Kategori / Jadwal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.index"><td>{{item.row[0]}}</td><td><strong>{{item.row[1]}}</strong></td><td>{{item.row[2]}}</td><td><span class="status">{{item.row[3]}}</span></td><td><div class="actions"><button title="Edit" @click="startEdit(item.index)"><Pencil :size="17"/></button><button title="Hapus" @click="remove(item.index)"><Trash2 :size="17"/></button></div></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty">Belum ada data yang sesuai.</td></tr></tbody></table></div></section><div v-if="modal" class="modal-backdrop" @click.self="modal=false"><form class="modal" @submit.prevent="save"><div class="modal-head"><h3>{{editing===-1?'Tambah':'Edit'}} {{title}}</h3><button type="button" class="icon-button" @click="modal=false"><X :size="19"/></button></div><label>Kode <input v-model="form[0]" required placeholder="Contoh: DT-003"/></label><label>Nama / Keterangan <input v-model="form[1]" required placeholder="Masukkan nama"/></label><label>Kategori / Jadwal <input v-model="form[2]" placeholder="Masukkan kategori"/></label><label>Status <select v-model="form[3]"><option>Aktif</option><option>Draft</option><option>Rencana</option><option>Nonaktif</option></select></label><div class="modal-actions"><button type="button" class="secondary-button" @click="modal=false">Batal</button><button type="submit" class="primary-button">Simpan</button></div></form></div></template>
